insert into public.drills (id, status, content) values
  ('airplanes', 'in_review', '{"funName":"Airplanes","plainName":"Glides, follow the leader","sourceTitle":"Follow the Leader: Glides","minutes":6,"gear":"None","worksAsStation":false,"description":"The coach leads a set of challenges across the ice. Pivot to face the other boards and back. Then glide across: on two skates, on one, with knees bent, with one leg stretched out. Finish with backward glides.","steps":["Pivot to face the other boards, then back.","Glide across: two skates, then one.","Backward glides on the way back."],"cues":["Proud chest, soft knees.","Hold it like a statue!"],"focus":[{"attribute":"Skating","level":2,"why":"Balance and glides on one skate."},{"attribute":"Effort & fun","level":1,"why":"“Bet you can’t do this one!”"}],"groupModel":"versions","source":{"label":"Hockey Canada U7 Plan 23 · no skill code","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-23-e.pdf","note":"We drew a line following the coach around the zone. In the source it is a progression of pivots and glides across the ice, led by the coach."},"diagram":{"scope":"half","side":"left","players":[{"role":"C","x":30,"y":6},{"role":"O","x":20,"y":10},{"role":"O","x":36,"y":10},{"role":"O","x":52,"y":10},{"role":"O","x":68,"y":10}],"paths":[{"type":"skate","points":[[20,13],[20,40],[20,72]],"step":2,"caption":"Glide across: two skates, then one."},{"type":"skate","points":[[36,13],[36,40],[36,72]],"stepWith":2},{"type":"skate","points":[[52,13],[52,40],[52,72]],"stepWith":2},{"type":"skate","points":[[68,13],[68,40],[68,72]],"stepWith":2},{"type":"backward","points":[[84,74],[84,45],[84,16]],"step":3,"stepSide":"right","caption":"Backward glides on the way back."}],"labels":[{"x":44,"y":3,"text":"pivot","size":2.6}]},"versions":[{"group":"Sharks","version":"Two-skate glides. Hold a coach’s hand if needed."},{"group":"Bears","version":"One-skate glides, both feet."},{"group":"Eagles","version":"Leg stretched out, then backward glides."}],"id":"airplanes"}'::jsonb),
  ('horse-and-buggy', 'in_review', '{"funName":"Horse and Buggy","plainName":"Power strides in pairs","sourceTitle":"Horse and Buggy","minutes":8,"gear":"2 sticks per pair","worksAsStation":true,"description":"Partners start at the boards. The horse holds the blades of two sticks and pulls; the buggy holds the shafts and glides behind. The buggy turns one foot to brake, so the horse has to push hard. Swap jobs for the trip back.","steps":["The horse pulls the buggy across the ice.","Swap jobs and come back."],"cues":["Horse: low and long strides.","Buggy: turn one foot to brake."],"focus":[{"attribute":"Skating","level":2,"why":"Power strides for the horse, balance on one edge for the buggy."},{"attribute":"Effort & fun","level":1,"why":"Racing in pairs."}],"groupModel":"stations","source":{"label":"Hockey Canada U7 Plan 8 · Phase 1 · skill 1.3.06","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-08-e.pdf","note":"We had the buggy riding along. In the source the buggy brakes on purpose, which is what makes the horse work hard."},"diagram":{"scope":"half","side":"left","stations":{"layout":"halfice","labels":["Race in pairs","Pairs","Coach pulls"],"groups":["Eagles","Bears","Sharks"]},"players":[{"role":"O","x":14,"y":20},{"role":"O","x":9,"y":20},{"role":"O","x":14,"y":32},{"role":"O","x":9,"y":32},{"role":"O","x":14,"y":68},{"role":"O","x":9,"y":68},{"role":"C","x":86,"y":38},{"role":"O","x":86,"y":31}],"paths":[{"type":"skate","points":[[17,20],[38,20],[58,20]],"step":1,"caption":"The horse pulls the buggy across the ice."},{"type":"skate","points":[[17,32],[38,32],[58,32]],"stepWith":1},{"type":"skate","points":[[17,68],[38,68],[58,68]],"stepWith":1},{"type":"skate","points":[[86,41],[86,58],[86,76]],"stepWith":1},{"type":"skate","points":[[58,77],[38,77],[17,77]],"step":2,"stepSide":"right","caption":"Swap jobs and come back."}]},"stations":[{"station":"A","group":"Eagles","version":"Buggy brakes hard. Race the next pair."},{"station":"B","group":"Bears","version":"Partners, light braking."},{"station":"C","group":"Sharks","version":"A coach is the horse. Sharks just glide and hold on."}],"id":"horse-and-buggy"}'::jsonb),
  ('hot-potato-partners', 'in_review', '{"funName":"Hot Potato Partners","plainName":"Passing on the move","sourceTitle":"Pairs Passing on the Move","minutes":8,"gear":"1 puck per pair","worksAsStation":true,"description":"Partners skate side by side around the zone, passing back and forth as they go. Make sure everyone gets passes on the forehand and the backhand.","steps":["Skate side by side around the zone.","Pass back and forth as you go."],"cues":["Stick on the ice: give a target.","Pass to where they’re going."],"focus":[{"attribute":"Passing","level":2,"why":"Passing and receiving while moving."},{"attribute":"Skating","level":1,"why":"Skating with a partner."},{"attribute":"Puck control","level":1,"why":"Settling a moving puck."}],"groupModel":"versions","source":{"label":"Hockey Canada U7 Plans 23, 30 · skills 2.4.01–2.4.02","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-23-e.pdf","note":"We drew partners standing still. In the source the pairs skate around the zone and pass on the move, forehand and backhand."},"diagram":{"scope":"half","side":"left","players":[{"role":"O","x":22,"y":22},{"role":"O","x":22,"y":34},{"role":"O","x":60,"y":58},{"role":"O","x":60,"y":70}],"paths":[{"type":"skate","points":[[24,22],[45,20],[64,24],[74,38]],"step":1,"caption":"Skate side by side around the zone."},{"type":"skate","points":[[24,34],[45,34],[60,38],[66,48]],"stepWith":1},{"type":"pass","points":[[40,21],[50,34]],"fromPlayer":false,"step":2,"stepSide":"right","caption":"Pass back and forth as you go."},{"type":"skate","points":[[58,58],[38,60],[22,52]]},{"type":"skate","points":[[58,70],[36,72],[18,64]]},{"type":"pass","points":[[42,72],[32,60]],"fromPlayer":false}]},"versions":[{"group":"Sharks","version":"Stand still and pass with a coach."},{"group":"Bears","version":"Skate slowly, pass on the forehand."},{"group":"Eagles","version":"Full speed, backhand passes too."}],"id":"hot-potato-partners"}'::jsonb),
  ('knock-the-tower', 'in_review', '{"funName":"Knock the Tower","plainName":"Hit-the-pylon scrimmage","sourceTitle":"Hit the Pylon Scrimmage","minutes":10,"gear":"1 cone, pinnies, pucks","worksAsStation":true,"description":"Small teams play across the ice. No nets, no goalies: one cone in the middle, and you score by hitting it with the puck. After a goal, give the puck to a coach, who sends it back in. Play never stops.","steps":["Score by hitting the cone.","Goal? Puck to the coach, who sends it back in."],"cues":["Find open ice!","Everyone back when they have it."],"focus":[{"attribute":"Game sense","level":2,"why":"Open ice, support, defending the cone."},{"attribute":"Effort & fun","level":2,"why":"A real game that never stops."},{"attribute":"Shooting","level":1,"why":"Hitting a small target."},{"attribute":"Puck control","level":1,"why":"Lots of touches in traffic."}],"groupModel":"stations","source":{"label":"Hockey Canada U7 Plans 15, 23 · no skill code","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-15-e.pdf","note":"We drew mini nets. In the source there are no nets or goalies: one pylon in the middle, and you score by hitting it."},"diagram":{"scope":"half","side":"left","stations":{"layout":"halfice","labels":["3 on 3, two pucks","3 on 3","2 on 2 + coach"],"groups":["Eagles","Bears","Sharks"]},"cones":[{"x":36,"y":26},{"x":36,"y":66},{"x":87,"y":50}],"players":[{"role":"O","x":20,"y":18},{"role":"O","x":24,"y":34},{"role":"O","x":48,"y":16},{"role":"X","x":52,"y":32},{"role":"X","x":30,"y":16},{"role":"X","x":16,"y":28},{"role":"O","x":20,"y":58},{"role":"O","x":26,"y":74},{"role":"O","x":48,"y":58},{"role":"X","x":50,"y":72},{"role":"X","x":40,"y":76},{"role":"X","x":16,"y":68},{"role":"C","x":58,"y":78},{"role":"O","x":82,"y":38},{"role":"O","x":92,"y":66},{"role":"X","x":82,"y":66},{"role":"X","x":92,"y":40},{"role":"C","x":93,"y":52}],"paths":[{"type":"puck","points":[[26,58],[30,62],[33,65]],"step":1,"caption":"Score by hitting the cone."},{"type":"shot","points":[[33,65],[35,66]],"fromPlayer":false,"stepWith":1},{"type":"puck","points":[[24,34],[29,30],[33,27.5]],"stepWith":1},{"type":"puck","points":[[48,16],[44,22]],"stepWith":1},{"type":"pass","points":[[56,76],[48,70]],"fromPlayer":false,"step":2,"stepSide":"right","caption":"Goal? Puck to the coach, who sends it back in."}]},"stations":[{"station":"A","group":"Eagles","version":"3 on 3 with a second puck when one team hogs it."},{"station":"B","group":"Bears","version":"3 on 3."},{"station":"C","group":"Sharks","version":"2 on 2 with a coach helping both teams."}],"id":"knock-the-tower"}'::jsonb),
  ('rotation-backwards-day', 'in_review', '{"funName":"Backwards Day","plainName":"Backward skating and stops, three zones","sourceTitle":"Phase II Lesson 11 skill stations","minutes":6,"gear":"4 pylons","worksAsStation":false,"description":"Three short skating stations. Groups move to the next zone on the whistle until everyone has done all three: walking backwards, gliding backwards off the boards, and stopping at each pylon.","steps":["A: walk backwards from the goal line toward the blue line.","B: push off the boards and glide backwards as far as you can.","C: skate to each pylon and stop facing the next one."],"cues":["Toes in, little steps back.","Sit in the chair.","Stop and look at the next pylon."],"focus":[{"attribute":"Skating","level":2,"why":"Backward stance, backward glide and stopping."},{"attribute":"Effort & fun","level":1,"why":"Beat your own glide."}],"groupModel":"rotation","zones":[{"station":"A","name":"Walk backwards","how":"Line up on the goal line facing the end boards, toes turned in. Walk backwards toward the blue line, lifting each skate.","cue":"Toes in, little steps back."},{"station":"B","name":"Backward glides","how":"Face the boards, push off with both hands and glide backwards as far as you can. Try to beat your last glide.","cue":"Sit in the chair."},{"station":"C","name":"Clock stops","how":"Skate to the first pylon and stop facing the next one. The next skater goes once you have stopped.","cue":"Stop and look at the next pylon."}],"source":{"label":"Hockey Canada U7 Phase II Lesson 11 · 1.5.03, 1.3.06","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf","note":"The source runs six stations in two sets. We kept three that fit the half-ice zones; Horse and Buggy and Toilet Bowl Tag are left for other plans."},"diagram":{"scope":"half","side":"left","stations":{"layout":"halfice","labels":["Walk backwards","Backward glides","Clock stops"]},"players":[{"role":"O","x":14,"y":12},{"role":"O","x":14,"y":22},{"role":"O","x":14,"y":32},{"role":"O","x":26,"y":80},{"role":"O","x":42,"y":80},{"role":"O","x":58,"y":80},{"role":"O","x":87,"y":14}],"paths":[{"type":"backward","points":[[16,12],[38,12],[58,12]],"step":1,"caption":"A: walk backwards from the goal line toward the blue line."},{"type":"backward","points":[[16,32],[36,32],[52,32]],"stepWith":1},{"type":"backward","points":[[26,78],[26,66],[26,56]],"step":2,"caption":"B: push off the boards and glide backwards as far as you can."},{"type":"backward","points":[[42,78],[42,62],[42,52]],"stepWith":2},{"type":"skate","points":[[87,16],[87,25]],"end":"stop","step":3,"caption":"C: skate to each pylon and stop facing the next one."},{"type":"skate","points":[[87,31],[87,41]],"end":"stop","stepWith":3}],"cones":[{"x":87,"y":28},{"x":87,"y":44},{"x":87,"y":60},{"x":87,"y":76}]},"id":"rotation-backwards-day"}'::jsonb),
  ('rotation-first-steps', 'in_review', '{"funName":"First Steps","plainName":"Getting up, C-cuts and glides, three zones","sourceTitle":"Phase I Lesson 2 skill stations","minutes":6,"gear":"None","worksAsStation":false,"description":"Three first-skating stations for early in the season. Groups move to the next zone on the whistle: getting up off the ice, C-cut pushes, and two-foot then one-foot glides.","steps":["A: get up into ready stance, then skate to the blue line.","B: glide on one foot and push C-cuts with the other.","C: a few strides, then glide on two feet, then one."],"cues":["Knees, hands, up!","Push a C, bring it home.","Freeze like a statue."],"focus":[{"attribute":"Skating","level":2,"why":"Getting up, stance, push and glide."},{"attribute":"Effort & fun","level":1,"why":"Falling and getting up is a game."}],"groupModel":"rotation","zones":[{"station":"A","name":"Get up!","how":"Lie on your back. On the whistle, roll over, get to your knees and stand up in ready stance. Then a few strides, drop to your knees, up again, skate to the blue line.","cue":"Knees, hands, up!"},{"station":"B","name":"C-cuts","how":"Glide on one foot and push C shapes with the other, three or four times. Then switch feet.","cue":"Push a C, bring it home."},{"station":"C","name":"Glide statues","how":"A few strides, then glide on two feet in ready stance like a statue. Then try one foot.","cue":"Freeze like a statue."}],"source":{"label":"Hockey Canada U7 Phase I Lesson 2 · 1.1.02, 1.4.01, 1.1.06–1.1.07","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-02-e.pdf","note":"The source offers four, two or six stations. We kept three that fit the half-ice zones; Fall Down, Simon Says and T-push are left for other plans."},"diagram":{"scope":"half","side":"left","stations":{"layout":"halfice","labels":["Get up!","C-cuts","Glide statues"]},"players":[{"role":"O","x":22,"y":18},{"role":"O","x":34,"y":18},{"role":"O","x":46,"y":18},{"role":"O","x":14,"y":60},{"role":"O","x":14,"y":72},{"role":"O","x":84,"y":16},{"role":"O","x":92,"y":16}],"paths":[{"type":"skate","points":[[22,21],[40,28],[60,30]],"step":1,"caption":"A: get up into ready stance, then skate to the blue line."},{"type":"skate","points":[[16,60],[40,60],[64,60]],"step":2,"caption":"B: glide on one foot and push C-cuts with the other."},{"type":"skate","points":[[16,72],[40,72],[64,72]],"stepWith":2},{"type":"skate","points":[[84,18],[84,46],[84,74]],"step":3,"caption":"C: a few strides, then glide on two feet, then one."}],"cones":[]},"id":"rotation-first-steps"}'::jsonb),
  ('rotation-puck-party', 'in_review', '{"funName":"Puck Party","plainName":"Puck control and gliding, three zones","sourceTitle":"Phase II Lesson 9 skill stations","minutes":6,"gear":"1 puck each","worksAsStation":false,"description":"Two puck stations and one skating station. Groups move to the next zone on the whistle: puck handling with eyes up, pushing the puck ahead while skating, and deep knee-bend glides.","steps":["A: move the puck side to side and call out the coach’s fingers.","B: push the puck ahead and chase it across the zone.","C: glide on one foot, bend low, hold it, stand tall."],"cues":["Eyes up, soft hands.","Push it, chase it.","Sit low, hold it, stand tall."],"focus":[{"attribute":"Puck control","level":2,"why":"Stickhandling with eyes up and skating with the puck."},{"attribute":"Skating","level":1,"why":"One-foot glide with a deep knee bend."}],"groupModel":"rotation","zones":[{"station":"A","name":"Finger count","how":"Stand spread out with a puck. Move it side to side, narrow then wide, and call out how many fingers the coach holds up.","cue":"Eyes up, soft hands."},{"station":"B","name":"Push and chase","how":"Start at the boards. Push the puck a little ahead, skate to it and push again, all the way across. Go in waves.","cue":"Push it, chase it."},{"station":"C","name":"Knee-bend glides","how":"A few strides, then glide on one foot. Bend the knee deep, hold it for two seconds, stand up. Switch feet.","cue":"Sit low, hold it, stand tall."}],"source":{"label":"Hockey Canada U7 Phase II Lesson 9 · 2.1.02–2.1.04, 1.1.09","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2022/u7-practice-plans-phase-2-e.pdf","note":"The source runs six stations in two sets. We kept three that fit the half-ice zones; the shooting stations and Inside Out are left for other plans."},"diagram":{"scope":"half","side":"left","stations":{"layout":"halfice","labels":["Finger count","Push and chase","Knee-bend glides"]},"players":[{"role":"O","x":18,"y":14},{"role":"O","x":32,"y":14},{"role":"O","x":46,"y":14},{"role":"O","x":25,"y":28},{"role":"O","x":39,"y":28},{"role":"C","x":62,"y":21},{"role":"O","x":10,"y":56},{"role":"O","x":10,"y":68},{"role":"O","x":10,"y":78},{"role":"O","x":82,"y":16},{"role":"O","x":92,"y":16}],"paths":[{"type":"puck","points":[[18,17],[22,19],[18,21],[22,23]],"step":1,"caption":"A: move the puck side to side and call out the coach’s fingers."},{"type":"puck","points":[[12,56],[38,56],[64,56]],"step":2,"caption":"B: push the puck ahead and chase it across the zone."},{"type":"puck","points":[[12,68],[36,68],[60,68]],"stepWith":2},{"type":"skate","points":[[82,18],[82,40],[82,70]],"step":3,"caption":"C: glide on one foot, bend low, hold it, stand tall."},{"type":"skate","points":[[92,18],[92,36],[92,62]],"stepWith":3}],"cones":[],"pucks":[{"x":21,"y":17},{"x":35,"y":17},{"x":49,"y":17},{"x":28,"y":31},{"x":42,"y":31}]},"id":"rotation-puck-party"}'::jsonb),
  ('ski-racer', 'in_review', '{"funName":"Ski Racer","plainName":"Tight turns through cones","sourceTitle":"Tight Turns","minutes":8,"gear":"5 cones","worksAsStation":true,"description":"Set up a zig-zag of cones from centre ice toward the net. Skate the course and turn tight around every cone. The next skater goes when the one ahead reaches the second cone.","steps":["Turn tight around every cone.","Next skater goes at the second cone."],"cues":["Knees bent, lean into the turn.","Look where you want to go."],"focus":[{"attribute":"Skating","level":2,"why":"Turning on both edges."}],"groupModel":"levels","source":{"label":"Hockey Canada U7 Plans 15, 30 · skill 1.6.02","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-15-e.pdf","note":"Right idea. The source adds a zig-zag course and a staggered start, so the line keeps moving."},"diagram":{"scope":"half","side":"left","cones":[{"x":77,"y":30},{"x":65,"y":52},{"x":53,"y":30},{"x":41,"y":52},{"x":29,"y":30}],"players":[{"role":"O","x":89,"y":42},{"role":"O","x":92,"y":49},{"role":"O","x":95,"y":56}],"paths":[{"type":"skate","points":[[89,42],[80,26],[73,32],[68,56],[61,50],[56,26],[49,32],[44,56],[37,50],[32,26],[25,32],[21,42]],"step":1,"caption":"Turn tight around every cone."},{"type":"skate","points":[[92,49],[84,36]],"step":2,"stepSide":"right","caption":"Next skater goes at the second cone."}]},"levels":[{"level":"1.0","name":"Skate the course","adds":"Tight turns, no puck.","groups":["Sharks"],"diagram":{"scope":"half","side":"left","cones":[{"x":77,"y":30},{"x":65,"y":52},{"x":53,"y":30},{"x":41,"y":52},{"x":29,"y":30}],"players":[{"role":"O","x":89,"y":42}],"paths":[{"type":"skate","points":[[89,42],[80,26],[73,32],[68,56],[61,50],[56,26],[49,32],[44,56],[37,50],[32,26],[25,32],[21,42]]}]}},{"level":"1.1","name":"Pass and shoot at the end","adds":"A coach passes as you come off the last cone. Shoot on the net.","groups":["Bears"],"diagram":{"scope":"half","side":"left","cones":[{"x":77,"y":30},{"x":65,"y":52},{"x":53,"y":30},{"x":41,"y":52},{"x":29,"y":30}],"players":[{"role":"O","x":89,"y":42},{"role":"C","x":20,"y":72}],"paths":[{"type":"skate","points":[[89,42],[80,26],[73,32],[68,56],[61,50],[56,26],[49,32],[44,56],[37,50],[32,26],[25,32],[21,42]]},{"type":"pass","points":[[20,69],[21,47]],"fromPlayer":false},{"type":"shot","points":[[21,42],[14,42.5]],"fromPlayer":false}]}},{"level":"1.2","name":"Carry it all the way","adds":"Puck on your stick through every turn, then shoot.","groups":["Eagles"],"diagram":{"scope":"half","side":"left","cones":[{"x":77,"y":30},{"x":65,"y":52},{"x":53,"y":30},{"x":41,"y":52},{"x":29,"y":30}],"players":[{"role":"O","x":89,"y":42}],"paths":[{"type":"puck","points":[[89,42],[80,26],[73,32],[68,56],[61,50],[56,26],[49,32],[44,56],[37,50],[32,26],[25,32],[21,42]]},{"type":"shot","points":[[21,42],[14,42.5]],"fromPlayer":false}]}}],"id":"ski-racer"}'::jsonb),
  ('snake-in-the-forest', 'in_review', '{"funName":"Snake in the Forest","plainName":"Weave, circle and shoot","sourceTitle":"Weave, Circle and Glide Turn","minutes":8,"gear":"1 puck each, 6 cones","worksAsStation":true,"description":"Start in the corner. Weave up the boards through four cones, skate a full circle around the fifth, glide-turn around the last one near the blue line, then come back down the middle to the net and shoot.","steps":["Weave up the boards, circle the fifth cone.","Glide turn at the last cone.","Come back down the middle and shoot."],"cues":["Soft hands, puck in front.","Peek up between cones."],"focus":[{"attribute":"Puck control","level":2,"why":"Moving puck control through turns."},{"attribute":"Skating","level":1,"why":"Edges and a glide turn."},{"attribute":"Passing","level":1,"why":"Receiving from the coach, and the give-and-go."},{"attribute":"Shooting","level":1,"why":"A shot to finish."}],"groupModel":"levels","source":{"label":"Hockey Canada U7 Plan 15 · skill 2.2.08","url":"https://cdn.hockeycanada.ca/hockey-canada/Hockey-Programs/Coaching/u7-program/downloads/2020/u7-practice-plan-15-e.pdf","note":"We had a plain slalom. The source adds a full circle around the fifth cone and a glide turn at the end. We kept those and changed the finish: out of the corner, up the boards, then back down to the net for a shot."},"diagram":{"scope":"half","side":"left","cones":[{"x":24,"y":64},{"x":34,"y":64},{"x":44,"y":64},{"x":54,"y":64},{"x":66,"y":64},{"x":84,"y":60}],"players":[{"role":"O","x":12,"y":74},{"role":"O","x":8,"y":78},{"role":"C","x":42,"y":22}],"paths":[{"type":"skate","points":[[12,74],[19,68],[29,60],[39,68],[49,60],[58,66],[62,58],[70,58],[71,69],[62,70],[64,62]],"step":1,"caption":"Weave up the boards, circle the fifth cone."},{"type":"skate","points":[[66,60],[78,56],[88,54],[90,62],[84,66]],"step":2,"stepSide":"right","caption":"Glide turn at the last cone."},{"type":"skate","points":[[82,62],[74,52],[58,44],[40,42],[26,42]]